<script setup>
import InsertObjectActions from "./InsertObjectActions.vue";
import ApplicationsMenu from './ApplicationsMenu.vue';
import WorkspaceHeader from './WorkspaceHeader.vue';
import {reactive,ref,onMounted,onUnmounted,inject} from 'vue';
import {Download,Play,LayoutGrid,Monitor,Check,Plus,Home,Clapperboard} from 'lucide-vue-next';
import {workflowNavigation} from '../workflowNavigation.js';
const navigation=inject(workflowNavigation,null);
function openPublicationLibrary(hash){active.value=null;sessionStorage.setItem('frame-publication-library-return',location.hash);navigation?.navigate(hash).catch(()=>{});}
const props=defineProps({studio:Object});const emit=defineEmits(['home','dashboard']);const s=reactive(props.studio),active=ref(null),root=ref(null);
function toggle(menu){active.value=active.value===menu?null:menu;}
function act(callback){active.value=null;callback();}
function outside(event){if(!root.value?.$el?.contains(event.target))active.value=null;}
onMounted(()=>document.addEventListener('pointerdown',outside));onUnmounted(()=>document.removeEventListener('pointerdown',outside));
</script>
<template><WorkspaceHeader ref="root" @keydown.esc.stop="active=null">
 <div class="app-header-left"><a class="brand header-brand" href="#" @click.prevent="!s.overlayVideoBusy&&!s.recording&&!s.finalizing&&!s.fileBusy&&emit('dashboard')" aria-label="Frame accueil"><span class="brand-icon">f</span><span class="brand-name">frame<span class="brand-dot">.</span></span></a><div class="workspace-nav-cluster"><button class="icon-btn navigation-return" :disabled="s.overlayVideoBusy||s.recording||s.finalizing||s.fileBusy" aria-label="Accueil" title="Accueil" @click="emit('dashboard')"><Home :size="18"/></button><button v-if="s.creationContext" class="icon-btn navigation-return" :disabled="s.overlayVideoBusy||s.recording||s.finalizing||s.fileBusy" aria-label="Vidéo" title="Vidéo" @click="emit('home')"><Clapperboard :size="18"/></button><nav class="app-menus" aria-label="Menus de l’application"><div v-for="menu in ['Fichier','Affichage','Projet','Insérer']" :key="menu" class="app-menu" v-show="menu!=='Insérer'||s.view!=='themes'"><button class="app-menu-trigger" :aria-expanded="active===menu" @click="toggle(menu)">{{menu}}</button><div v-if="active===menu" class="app-menu-popover" :aria-label="'Menu '+menu">
 <template v-if="menu==='Fichier'"><button v-if="s.openSupported" :disabled="s.fileBusy" @click="act(()=>s.openProject())">Ouvrir un fichier lié</button><label class="menu-file">Importer un document JSON<input type="file" accept="application/json" @change="s.importProject($event);active=null"></label><hr><button :disabled="s.fileBusy" @click="act(()=>s.saveProject(false))">Enregistrer <kbd>Ctrl S</kbd></button><button :disabled="s.fileBusy" @click="act(()=>s.saveProject(true))">Enregistrer sous… <kbd>Ctrl Maj S</kbd></button><button @click="act(()=>s.exportProject())">{{s.isAnimation?'Exporter l’animation JSON':s.isThumbnail?'Exporter la miniature JSON':s.documentScope==='banners'?'Exporter l’incrustation JSON':'Exporter le diaporama JSON'}}</button><button v-if="s.view!=='themes'" @click="act(()=>s.png())">{{s.isAnimation?'Exporter l’image PNG à cet instant':s.isThumbnail?'Exporter la miniature PNG':s.view==='banners'?'Exporter le PNG transparent':'Exporter la diapo PNG'}}</button><template v-if="s.isAnimation"><hr><button @click="act(()=>s.saveEditorView())">Enregistrer la configuration de l’interface…</button><button @click="act(()=>s.exportEditorView())">Exporter la configuration de l’interface</button><label class="menu-file">Importer une configuration d’interface<input type="file" accept="application/json,.json" @change="s.importEditorView($event);active=null"></label></template><button v-if="s.view==='banners'" @click="act(()=>s.openOverlayVideo())">Exporter une incrustation animée…</button><hr><button @click="act(()=>s.view='themes')">Thèmes</button><button @click="openPublicationLibrary('#/musiques')">Bibliothèque de musiques</button><button @click="openPublicationLibrary('#/modeles-description')">Modèles de description</button><hr><button :disabled="s.overlayVideoBusy||s.recording||s.finalizing||s.fileBusy" @click="act(()=>navigation?.openBackup())">Sauvegarde globale…</button><small v-if="s.fileName">{{s.fileName}}{{s.fileDirty?' · modifié':''}}</small></template>
 <template v-else-if="menu==='Affichage'"><label v-for="[key,name] in [['properties','Propriétés'],['slides','Liste des diapos'],['toolbar','Conseil de l’atelier']]" :key="key" v-show="s.application==='slides'||!['slides','toolbar'].includes(key)" class="menu-checkbox"><input type="checkbox" v-model="s.panels[key]">{{name}}</label><hr><button v-if="s.view==='slides'&&!s.isThumbnail&&!s.creationContext?.componentEditor" @click="act(()=>{s.workspace='canvas';s.closeEdit();})">{{s.isAnimation?'Voir le canvas des scènes':'Voir le canvas du diaporama'}}</button><button v-if="s.view==='slides'&&!s.isThumbnail&&!s.creationContext?.componentEditor" @click="act(()=>s.workspace='editor')">{{s.isAnimation?'Éditer la scène':'Éditer la diapo'}}</button></template>
 <template v-else-if="menu==='Projet'"><label>{{s.isAnimation?'Nom de l’animation':s.isThumbnail?'Nom de la miniature':s.documentScope==='banners'?'Nom de l’incrustation':'Nom du diaporama'}}<input type="text" v-model="s.project" maxlength="200" aria-label="Nom du projet"></label><small>{{s.isAnimation?s.slides.length+' scène(s) · 16:9':s.isThumbnail?'Miniature · 16:9':s.documentScope==='banners'?'Incrustation · 16:9':s.slides.length+' diapo'+(s.slides.length>1?'s':'')+' · 16:9'}}</small><button @click="act(()=>{s.formatWidth=s.resolution.width;s.formatOpen=true;})">Format · {{s.resolution.width}} × {{s.resolution.height}} px</button><button @click="act(()=>s.view='themes')">Thème et palette du projet</button></template>
 <template v-else><InsertObjectActions :studio="s" @done="active=null"/><hr><button v-if="s.view==='slides'&&!s.isThumbnail&&!s.creationContext?.componentEditor" @click="act(()=>s.add())">{{s.isAnimation?'Nouvelle scène':'Nouvelle diapo'}}</button></template>
 </div></div><ApplicationsMenu :disabled="s.overlayVideoBusy||s.recording||s.finalizing||s.fileBusy||s.animation?.busy" @open="active=null"/></nav></div><span v-if="s.creationContext" class="creation-context-name" :title="s.creationContext.videoName+' / '+s.project">{{s.creationContext.videoName}} / {{s.project}}</span><span class="application-name">{{s.isAnimation?'Animation':s.isThumbnail?'Miniatures':s.application==='banners'?'Incrustations':'Diaporamas'}}</span></div>
 <div class="app-header-right"><template v-if="s.creationContext?.componentEditor"><button class="btn" @click="s.creationContext.componentEditor.discard()">Fermer</button><button class="btn primary" :disabled="s.creationContext.componentEditor.saving" @click="s.creationContext.componentEditor.save()"><Check :size="16"/>Enregistrer le composant</button></template><button v-if="s.isAnimation" class="btn primary" :disabled="s.animation.busy" @click="s.animation.preview=true;s.animation.previewOpen=true"><Play :size="16"/>Animer / Exporter</button><details v-if="s.isAnimation" class="animation-examples"><summary>Exemples</summary><div><button class="btn" @click="s.animation.example('effects')">Laboratoire d’effets · quatre scènes</button><button class="btn" @click="s.animation.example('gc')">Garbage Collector</button><button class="btn" @click="s.animation.example('pool')">String Pool</button><button class="btn" @click="s.animation.example('reference')">Référence Java · événements</button><button class="btn" @click="s.animation.example('slime')">Slime · cinq mondes</button></div></details><span class="save-state" :title="s.saved?'Sauvegardé sur cet appareil':'Sauvegarde en cours'"><Check :size="14" v-if="s.saved"/><span>{{s.saved?(s.isAnimation?'Animation sauvegardée':s.isThumbnail?'Miniature sauvegardée':s.documentScope==='banners'?'Incrustation sauvegardée':'Diaporama sauvegardé'):'Sauvegarde…'}}</span></span><button v-if="s.isThumbnail" class="btn" @click="s.gallery=true"><LayoutGrid :size="16"/>Playlists</button><button v-if="s.isThumbnail" class="btn primary" @click="s.png()">Exporter le PNG</button><div class="workspace-switch" v-if="s.view==='slides'&&!s.isThumbnail&&!s.creationContext?.componentEditor"><button :class="{active:s.workspace==='editor'}" aria-label="Éditer" @click="s.workspace='editor'"><Monitor :size="15"/><span>Éditer</span></button><button :class="{active:s.workspace==='canvas'}" aria-label="Canvas" @click="s.workspace='canvas';s.closeEdit()"><LayoutGrid :size="15"/><span>Canvas</span></button></div><button v-if="s.view==='banners'" class="btn primary" @click="s.openOverlayVideo()"><Play :size="16"/>Animer</button><button v-if="s.view==='banners'" class="btn" @click="s.overlayGallery=true"><LayoutGrid :size="16"/>Formats</button><button class="btn primary" v-if="s.view==='slides'&&!s.isThumbnail&&!s.isAnimation&&!s.creationContext?.componentEditor" @click="s.startPresenter()" title="Lancer la présentation · F12" aria-keyshortcuts="F12"><Play :size="16"/><span>Présenter</span></button></div>
</WorkspaceHeader></template>
